import{_ as i,D as d,o as r,c as h,j as o,a as e,I as l,w as a,am as n}from"./chunks/framework.DXw8qDd0.js";const P=JSON.parse('{"title":"Codex手机端协同指南","description":"","frontmatter":{"title":"Codex手机端协同指南","time":"2026-06-07T00:00:00.000Z","tags":["codex"]},"headers":[],"relativePath":"笔记/Codex/Codex手机端协同指南.md","filePath":"笔记/Codex/Codex手机端协同指南.md"}'),x={name:"笔记/Codex/Codex手机端协同指南.md"},c=o("h1",{id:"用手机端-codex-跟进桌面任务",tabindex:"-1"},[e("用手机端 Codex 跟进桌面任务 "),o("a",{class:"header-anchor",href:"#用手机端-codex-跟进桌面任务","aria-label":'Permalink to "用手机端 Codex 跟进桌面任务"'},"​")],-1),s=n('<hr><h2 id="这是什么" tabindex="-1">这是什么 <a class="header-anchor" href="#这是什么" aria-label="Permalink to &quot;这是什么&quot;">​</a></h2><p>手机端 Codex 不是一个独立的 App，也不是把手机变成远程桌面鼠标键盘。</p><p>你可以把它理解成：桌面 App、远程开发机或其他已授权环境里正在运行 Codex，手机端负责连接这些环境，让你在离开电脑时继续查看、回复、审批和调整任务。</p><p>真正执行任务的地方仍然是桌面 App 或远程环境，你的文件、依赖、凭证、权限和本地配置不会因为手机端接入而搬到手机上。</p><hr><h2 id="使用前提" tabindex="-1">使用前提 <a class="header-anchor" href="#使用前提" aria-label="Permalink to &quot;使用前提&quot;">​</a></h2><ol><li>手机上安装并更新 ChatGPT App。</li><li>电脑上安装并更新 Codex 桌面 App。</li><li>手机和电脑登录同一个 ChatGPT / OpenAI 账号，且处于支持 Codex 的地区和套餐范围内。</li><li>桌面 App 已连接到对应项目，或 Codex 正在某台已授权机器、devbox、远程环境中运行。</li><li>如果任务会写文件、跑命令、访问网络，仍然需要理解并确认对应权限。</li></ol><hr><h2 id="它能做什么" tabindex="-1">它能做什么 <a class="header-anchor" href="#它能做什么" aria-label="Permalink to &quot;它能做什么&quot;">​</a></h2><p>手机端连接到正在运行 Codex 的机器后，可以继续处理这些事情：</p><ol><li>查看正在进行的线程和任务状态。</li><li>阅读 Codex 的阶段性输出、终端输出、截图、diff 和测试结果。</li><li>回复 Codex 的澄清问题。</li><li>审批命令、网络访问或其他需要人工确认的操作。</li><li>改变任务方向、切换模型或补充新的上下文。</li><li>新建任务，让 Codex 从已连接的开发环境里开始工作。</li></ol><hr><h2 id="推荐使用场景" tabindex="-1">推荐使用场景 <a class="header-anchor" href="#推荐使用场景" aria-label="Permalink to &quot;推荐使用场景&quot;">​</a></h2><p>手机端最适合处理「离开电脑但不想让任务停下」的时刻：</p><ol><li>通勤路上查看长任务进展。</li><li>Codex 需要你选择方案时，快速给出方向。</li><li>任务卡在权限审批时，从手机上批准或拒绝。</li><li>会议前让 Codex 汇总最新代码、issue、文档或客户背景。</li><li>突然想到一个改动点，先发给 Codex 开始探索，回到电脑后再细看 diff。</li></ol><hr><h2 id="不适合怎么用" tabindex="-1">不适合怎么用 <a class="header-anchor" href="#不适合怎么用" aria-label="Permalink to &quot;不适合怎么用&quot;">​</a></h2><p>手机端不适合替代完整的本地审查流程。下面这些事情最好回到电脑上做：</p><ol><li>大范围代码合并前的最终 review。</li><li>涉及生产环境、密钥、账单、发布部署的高风险操作。</li><li>需要长时间阅读大量 diff 的任务。</li><li>需要你手动操作 IDE、调试器或本地 GUI 的任务。</li></ol><p>如果你在手机上审批命令，建议只批准自己能看懂的操作。遇到删除、覆盖、部署、传输敏感数据等动作，先停下来，回到电脑上确认。</p><hr><h2 id="一个典型流程" tabindex="-1">一个典型流程 <a class="header-anchor" href="#一个典型流程" aria-label="Permalink to &quot;一个典型流程&quot;">​</a></h2><ol><li>在电脑上打开 Codex 桌面 App，并进入对应项目。</li><li>让 Codex 开始一个需要较长时间的任务，比如排查失败测试或整理文档。</li><li>离开电脑后，在 ChatGPT 手机 App 中进入 Codex。</li><li>打开同一个正在运行的任务线程。</li><li>查看 Codex 的输出、截图、终端日志、测试结果或 diff。</li><li>如果 Codex 需要确认，直接在手机上回复、审批或调整方向。</li><li>回到电脑后，再做完整 diff review、运行验证命令和提交。</li></ol><hr><h2 id="和-codex-cloud-的区别" tabindex="-1">和 Codex Cloud 的区别 <a class="header-anchor" href="#和-codex-cloud-的区别" aria-label="Permalink to &quot;和 Codex Cloud 的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th>对比项</th><th>手机端连接桌面 App</th><th>Codex Cloud</th></tr></thead><tbody><tr><td>执行位置</td><td>你的电脑、devbox 或远程环境</td><td>OpenAI / ChatGPT 连接的云端任务环境</td></tr><tr><td>文件与凭证</td><td>留在原机器上</td><td>依赖云端连接的仓库与授权</td></tr><tr><td>适合任务</td><td>跟进本地长任务、审批、查看结果</td><td>不依赖本地电脑的仓库任务</td></tr><tr><td>是否能离开电脑</td><td>可以，但原执行环境要可连接</td><td>可以</td></tr></tbody></table><p>一句话：<strong>手机端 Codex 更像「随身工作台」，Codex Cloud 更像「云端执行环境」。</strong></p><hr><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>手机端的价值不在于替代电脑，而在于让你在碎片时间里持续推进任务。</li><li>真正的执行、验证和高风险操作，仍建议回到电脑上完成。</li><li>如果你在手机上审批，只批准自己看得懂的操作；不确定的先停下，回到电脑上确认。</li></ul><hr>',32);function p(C,u,_,f,b,m){const t=d("VPNolebaseInlineLinkPreview");return r(),h("div",null,[c,o("blockquote",null,[o("p",null,[e("来源：CodexGuide - 手机端协同 ("),l(t,{href:"https://codexguide.ai/guide/04-mobile-control-desktop.html",target:"_blank",rel:"noreferrer"},{default:a(()=>[e("https://codexguide.ai/guide/04-mobile-control-desktop.html")]),_:1}),e(") 官方文章：Work with Codex from anywhere ("),l(t,{href:"https://openai.com/index/work-with-codex-from-anywhere/",target:"_blank",rel:"noreferrer"},{default:a(()=>[e("https://openai.com/index/work-with-codex-from-anywhere/")]),_:1}),e(")")])]),s,o("blockquote",null,[o("p",null,[e("📎 "),l(t,{href:"/ocdsync/笔记/"},{default:a(()=>[e("📒 返回笔记索引")]),_:1})])])])}const q=i(x,[["render",p]]);export{P as __pageData,q as default};
